@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetMediaItemTake_Track, reaper.GetTakeName, reaper.MIDI_SetAllEvts, reaper.MIDI_GetAllEvts, reaper.CountTrackMediaItems, reaper.SetMediaItemSelected, reaper:setCursor, reaper:setSelectedTracks, reaper:setLoopRange, reaper.GetSetRepeat, reaper:setPlay, reaper.GetMediaItemTakeInfo_Value, reaper.SetMediaItemTakeInfo_Value, r._state.playState

# Intent
  arrangeManager: discovery, slot auto-allocation, placement, reswing.

# Helpers
  @fn mkAm(harness, opts)  @ 7-12
  @fn seedTracks(h, specs)  @ 18-40
      -- Seed two arbitrary tracks and a per-track item list. Returns the
      -- track tokens so each test can name them. The harness's default
      -- bindTake(take1) is unrelated — we manage these via setProjectTracks
      -- so am sees them in CountTracks/GetTrack order.
  @fn slotFor(am, trackIdx, id)  @ 42-44
  @fn slotAt(am, trackIdx, slotIdx)  @ 46-48

# Cases
  @case 'projectTracks lists every track in REAPER order with item count'  [harness]  @ 55-71
  @case 'trackSlots auto-allocates slot indices for live takes'  [harness]  @ 78-92
  @case 'tracksTakes assigns slotIdx to every grouped take'  [harness]  @ 96-114
  @case 'ensureSlots is idempotent — second read does not reallocate'  [harness]  @ 118-129
  @case 'hasPlacedTakes ignores parked takes, sees placed instances'  [harness]  @ 133-142
  @case 'ownerTrack resolves a parked take to its logical track, not scratch'  [harness]  @ 149-163
  @case 'renameSlot writes SetTakeName across every matching item'  [harness]  @ 170-183
  @case 'renameSlot reroots the family, each slot keeping its own ordinal'  [harness]  @ 187-204
  @case 'renameSlot with a changed ordinal renames that slot alone'  [harness]  @ 208-218
  @case 'an unnamed slot has no family'  [harness]  @ 222-232
  @case 'the reroot reaches a parked family member'  [harness]  @ 236-245
  @case 'renameSlot renames a parked slot through its keeper'  [harness]  @ 249-256
  @case 'deleteSlot removes every matching item and prunes the dict entry'  [harness]  @ 260-278
  @case 'createAndDropMidi mints slot 0, creates a take, names it'  [harness]  @ 285-301
  @case 'createAndDropMidi allocates lowest-free index across calls'  [harness]  @ 305-316
  @case 'dropInstance pools to an existing slot'  [harness]  @ 320-331
  @case 'dropInstance overwrites a take already starting at the drop position'  [harness]  @ 335-352
  @case 'createAndDropMidi overwrites a take already starting at the create position'  [harness]  @ 356-371
  @case 'dropInstance returns nil for missing slot or missing track'  [harness]  @ 375-381
  @case 'duplicateTake clones a MIDI take into a pooled sibling'  [harness]  @ 385-400
  @case 'dropInstance and duplicateTake name the new take after the slot'  [harness]  @ 404-415
  @case 'duplicateTake returns nil for a missing track'  [harness]  @ 419-427
  @case 'dropInstance carries the sibling MIDI events into the new instance'  [harness]  @ 431-441
  @case 'duplicateTake carries the source MIDI events into the clone'  [harness]  @ 445-456
  @case 'startIsClear only collides on an exact start match (item ~= exceptItem)'  [harness]  @ 460-475
  @case 'createAndDropMidi returns nil when no track exists'  [harness]  @ 479-484
  @case 'keyForSlot maps 0..61 through util.toBase62'  [harness]  @ 491-500
  @case 'takesUsing scans each take swing map (ds) for the named swing'  [harness]  @ 507-525
  @case 'tempersInUse unions take/project temper names, minus the 12EDO floor'  [harness]  @ 528-542
  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 552-561
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 564-575
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 578-586
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 590-604
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 608-624
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 627-642
  @case 'trimmed audio take keeps its trim across a move (no balloon to source)'  [harness]  @ 645-657
  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 661-672
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 676-687
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 691-702
  @case 'deleteTake parks a slot\'s last instance; the slot survives, greyed'  [harness]  @ 708-724
  @case 'deleteTake of a non-last instance deletes outright (no park)'  [harness]  @ 728-743
  @case 're-dropping from a parked slot re-materialises off the keeper'  [harness]  @ 747-760
  @case 'deleteSlot forever-deletes: live instances and the parked keeper'  [harness]  @ 764-777
  @case 'deleteSlot forever-deletes the pool per-event metadata'  [harness]  @ 781-792
  @case 'mintParkedTake shows the new slot at once; isParkedTake flags scratch-hosted takes'  [harness]  @ 796-811
  @case 'vary replaces the instance with one of a fresh variant slot'  [harness]  @ 818-840
  @case 'vary numbers from the family high-water mark; a variant of a variant joins the family'  [harness]  @ 844-855
  @case 'vary refuses on a slot with a single instance'  [harness]  @ 859-867
  @case 'findTake resolves a REAPER take handle back to its grid take-shape'  [harness]  @ 874-888
  @case 'initialCursor reads the selected item: its take track and start'  [harness]  @ 892-904
  @case 'initialCursor falls back to the edit cursor and selected track'  [harness]  @ 908-917
  @case 'initialCursor defaults to track 0 when nothing is selected'  [harness]  @ 921-929
  @case 'editCursorQN reads the REAPER edit cursor'  [harness]  @ 936-941
  @case 'setEditCursorQN moves the REAPER edit cursor'  [harness]  @ 945-950
  @case 'loopRangeQN returns the project loop range'  [harness]  @ 954-961
  @case 'loopRangeQN is nil when no loop is set'  [harness]  @ 965-969
  @case 'setLoopRangeQN writes the project loop range'  [harness]  @ 973-980
  @case 'loopTo brackets a span: loop range, repeat on, cursor at its start'  [harness]  @ 984-992
  @case 'loopTo leaves the cursor alone when the play head is inside the span'  [harness]  @ 996-1005
  @case 'clearLoopRange removes the project loop range'  [harness]  @ 1009-1015
  @case 'playPositionQN is nil when the transport is stopped'  [harness]  @ 1019-1023
  @case 'playPositionQN returns the play head qn while playing'  [harness]  @ 1027-1032
  @case 'seekInstance takes the instance whose rendered span holds qn'  [harness]  @ 1039-1053
  @case 'seekInstance spans are half-open — the end belongs to the next'  [harness]  @ 1057-1066
  @case 'seekInstance from a gap travels forwards by default, backwards when asked'  [harness]  @ 1070-1082
  @case 'seekInstance falls back to the other direction when its own is empty'  [harness]  @ 1086-1096
  @case 'seekInstance ignores instances of other slots'  [harness]  @ 1100-1112
  @case 'seekInstance matches on the rendered span, not the source span'  [harness]  @ 1116-1128
  @case 'seekInstance is nil for a slot whose only take is parked'  [harness]  @ 1132-1142
  @case 'projectEndQN is 0 for a project with no items'  [harness]  @ 1146-1150
  @case 'projectEndQN reports the largest take end across all tracks'  [harness]  @ 1154-1163
  @case 'freeSpan is the gap to the next take, and unbounded past the last'  [harness]  @ 1170-1180
  @case 'duplicateBelow places a pooled clone at the append point'  [harness]  @ 1184-1200
  @case 'duplicateBelow refuses where a truncating neighbour leaves no room'  [harness]  @ 1204-1220
  @case 'duplicateBelow refuses where the gap is shorter than the natural length'  [harness]  @ 1224-1235
  @case 'duplicateBelow refuses on exact-start collision at the destination'  [harness]  @ 1239-1249
  @case 'duplicateBelow refuses on audio takes'  [harness]  @ 1253-1262
  @case 'duplicateUnpooledBelow mints a fresh slot and copies the MIDI blob'  [harness]  @ 1266-1286
  @case 'duplicateUnpooledBelow forks the source per-event metadata onto the fresh pool'  [harness]  @ 1292-1303
  @case 'duplicateUnpooledBelow parks the clone for want of room'  [harness]  @ 1307-1324
  @case 'duplicateUnpooledBelow refuses on audio'  [harness]  @ 1328-1336
  @case 'newTakeBelow creates an empty MIDI take of the asked-for length at the append point'  [harness]  @ 1340-1361
  @case 'newTakeBelow parks the take for want of room'  [harness]  @ 1365-1377
  @case 'newTakeBelow measures the room against the length asked for'  [harness]  @ 1381-1392
  @case 'newTakeBelow refuses on audio'  [harness]  @ 1396-1404
  @case 'distinct pool guids on different tracks get distinct colourIdx'  [harness]  @ 1409-1422
  @case 'pooled instances on different tracks share one colourIdx'  [harness]  @ 1426-1436
  @case 'createAndDropMidi stamps I_CUSTOMCOLOR on the new take'  [harness]  @ 1440-1448
  @case 'duplicateUnpooledBelow strips the source colour and mints a fresh one'  [harness]  @ 1452-1468
  @case 'placement does not overwrite a pre-existing take colour (preserve override)'  [harness]  @ 1472-1484
  @case 'a recycled take handle reports the new item\'s pool, not the dead take\'s'  [harness]  @ 1489-1512

